 ## Unreleased

+- Reject invalid items and normalize names and tags when adding items.
 - Faster tag lookup.

 ## 1.4.2 - 2026-09-30
diff --git a/src/items.js b/src/items.js
index b1cae5b..cd88e75 100644
--- a/src/items.js
+++ b/src/items.js
@@ -8,8 +8,16 @@ export async function findByTag(tag) {

 /** Adds an item with the next free id. */
 export async function addItem(item) {
-  if (!item.name) throw new Error("Item needs a name.");
+  if (!item || typeof item !== "object" || Array.isArray(item)) throw new Error("Invalid item.");
+  if (typeof item.name !== "string" || !item.name.trim()) throw new Error("Item needs a name.");
+  if (!Number.isSafeInteger(item.qty) || item.qty < 0) throw new Error("Invalid quantity.");
+  if (item.unit !== undefined && (typeof item.unit !== "string" || !/^(?:[a-zA-Z]+)?$/.test(item.unit))) throw new Error("Invalid unit.");
+  if (item.tags !== undefined && (!Array.isArray(item.tags) || item.tags.some((tag) => typeof tag !== "string"))) throw new Error("Invalid tags.");
+  if (typeof item.expires !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(item.expires)) throw new Error("Invalid expiry date.");
+  const date = new Date(`${item.expires}T00:00:00.000Z`);
+  if (Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== item.expires) throw new Error("Invalid expiry date.");
   const items = await fetchItems();
   const id = Math.max(0, ...items.map((i) => i.id)) + 1;
-  return saveItem({ tags: [], unit: "", ...item, id });
+  const tags = [...new Set((item.tags ?? []).map((tag) => tag.toLowerCase()))].sort();
+  return saveItem({ unit: "", ...item, name: item.name.trim().toLowerCase(), tags, id });
 }
